ST = {"vp": "Làm trái quy định", "hs": "Cần hồ sơ", "ct": "Cần cải thiện", "ok": "Không có vấn đề", "tt": "Thông tin"}
# muc bao cao -> chu de hoi dap (lien ket o o ket luan tung muc)
SEC_TOPIC = {"01": "tong-quat", "02": "tin-cay", "03": "tin-cay", "04": "so-du", "05": "khoan-chi", "06": "kvc", "07": "lai-suat",
             "08": "an-toan", "09": "quy-dinh", "10": "quy-dinh", "11": "tong-quat", "12": "cu-dan"}


def build():
    tids = [t["id"] for t in TOPICS]
    ids = set()
    for it in ITEMS:
        assert it["t"] in tids, it["id"]
        assert it["st"] in ST, it["id"]
        assert it["id"] not in ids, it["id"]
        ids.add(it["id"])
        it.setdefault("d", []); it.setdefault("n", []); it.setdefault("go", []); it.setdefault("c", []); it.setdefault("k", "")
        for s in [it["q"], it["a"]] + it["d"]:
            assert "→" not in s and "->" not in s, it["id"]
    for t in TOPICS:
        assert any(i["t"] == t["id"] for i in ITEMS), t["id"]
    return dict(topics=TOPICS, items=ITEMS, st=ST, sec=SEC_TOPIC)
